1	package netdiag
2	
3	import (
4		"net"
5		"net/netip"
6		"slices"
7		"testing"
8		"time"
9	
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/netcheck"
13		"github.com/anthnel/devdesk/internal/nettrace"
14	)
15	
16	var (
17		stepsRoute = &pathRoute{
18			Known:     true,
19			Interface: "wlan0",
20			Source:    netip.MustParseAddr("192.168.1.21"),
21			Gateway:   netip.MustParseAddr("192.168.1.1"),
22		}
23		stepsHop1 = nettrace.Hop{TTL: 1, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("192.168.1.1"), RTT: 2 * time.Millisecond}
24		stepsHop2 = nettrace.Hop{TTL: 2, Kind: nettrace.HopSilent}
25		stepsHop3 = nettrace.Hop{TTL: 3, Kind: nettrace.HopTarget, Addr: netip.MustParseAddr("1.1.1.1"), RTT: 12300 * time.Microsecond}
26	)
27	
28	func stepKinds(steps []pathStep) []pathStepKind {
29		kinds := make([]pathStepKind, len(steps))
30		for i, s := range steps {
31			kinds[i] = s.Kind
32		}
33		return kinds
34	}
35	
36	func TestPathStepsNewPathRoute(t *testing.T) {
37		tests := []struct {
38			name string
39			hop  netcheck.RouteHop
40			err  error
41			want pathRoute
42		}{
43			{
44				name: "all fields",
45				hop: netcheck.RouteHop{
46					Interface: "eth0",
47					Source:    net.IPv4(192, 168, 1, 21),
48					Gateway:   net.IPv4(192, 168, 1, 1),
49				},
50				want: pathRoute{
51					Known:     true,
52					Interface: "eth0",
53					Source:    netip.MustParseAddr("192.168.1.21"),
54					Gateway:   netip.MustParseAddr("192.168.1.1"),
55				},
56			},
57			{
58				name: "no gateway means directly connected",
59				hop:  netcheck.RouteHop{Interface: "eth0", Source: net.ParseIP("10.0.0.2")},
60				want: pathRoute{Known: true, Interface: "eth0", Source: netip.MustParseAddr("10.0.0.2")},
61			},
62			{
63				name: "no source",
64				hop:  netcheck.RouteHop{Interface: "tun0", Gateway: net.ParseIP("10.0.0.1")},
65				want: pathRoute{Known: true, Interface: "tun0", Gateway: netip.MustParseAddr("10.0.0.1")},
66			},
67			{
68				name: "an error discards whatever the hop holds",
69				hop:  netcheck.RouteHop{Interface: "eth0", Source: net.ParseIP("10.0.0.2")},
70				err:  net.ErrClosed,
71				want: pathRoute{},
72			},
73		}
74		for _, tt := range tests {
75			t.Run(tt.name, func(t *testing.T) {
76				got := newPathRoute(tt.hop, tt.err)
77				if got != tt.want {
78					t.Fatalf("newPathRoute = %+v, want %+v", got, tt.want)
79				}
80				if got.Source.IsValid() && !got.Source.Is4() {
81					t.Errorf("source %v must be unmapped to IPv4", got.Source)
82				}
83				if got.Gateway.IsValid() && !got.Gateway.Is4() {
84					t.Errorf("gateway %v must be unmapped to IPv4", got.Gateway)
85				}
86			})
87		}
88	}
89	
90	func TestPathStepsOrder(t *testing.T) {
91		unknown := &pathRoute{Known: false}
92		tests := []struct {
93			name  string
94			route *pathRoute
95			hops  []nettrace.Hop
96			want  []pathStepKind
97			hopTT []int // TTLs of the stepHop rows, in order
98		}{
99			{"nothing known yet", nil, nil, nil, nil},
100			{"route, no hop yet", stepsRoute, nil,
101				[]pathStepKind{stepSource, stepInterface, stepGateway}, nil},
102			{"criterion 1: source, interface, gateway, then sorted hops", stepsRoute,
103				[]nettrace.Hop{stepsHop3, stepsHop1},
104				[]pathStepKind{stepSource, stepInterface, stepGateway, stepHop, stepHop}, []int{1, 3}},
105			{"hop before route: the source still comes first", nil,
106				[]nettrace.Hop{stepsHop1},
107				[]pathStepKind{stepSource, stepHop}, []int{1}},
108			{"failed lookup keeps the three local rows", unknown,
109				[]nettrace.Hop{stepsHop1, stepsHop2},
110				[]pathStepKind{stepSource, stepInterface, stepGateway, stepHop, stepHop}, []int{1, 2}},
111			{"empty hop list", stepsRoute, []nettrace.Hop{},
112				[]pathStepKind{stepSource, stepInterface, stepGateway}, nil},
113			{"unresolved hops are dropped and the list is cut after the target", stepsRoute,
114				[]nettrace.Hop{
115					stepsHop3,
116					{TTL: 2, Kind: nettrace.HopUnresolved},
117					{TTL: 4, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("9.9.9.9")},
118					stepsHop1,
119				},
120				[]pathStepKind{stepSource, stepInterface, stepGateway, stepHop, stepHop}, []int{1, 3}},
121		}
122		for _, tt := range tests {
123			t.Run(tt.name, func(t *testing.T) {
124				hopsBefore := slices.Clone(tt.hops)
125				var routeBefore pathRoute
126				if tt.route != nil {
127					routeBefore = *tt.route
128				}
129	
130				got := pathSteps(tt.route, tt.hops)
131	
132				if kinds := stepKinds(got); !slices.Equal(kinds, tt.want) {
133					t.Fatalf("kinds = %v, want %v", kinds, tt.want)
134				}
135				var ttls []int
136				for _, s := range got {
137					if s.Kind == stepHop {
138						ttls = append(ttls, s.Hop.TTL)
139					}
140				}
141				if !slices.Equal(ttls, tt.hopTT) {
142					t.Errorf("hop TTLs = %v, want %v", ttls, tt.hopTT)
143				}
