1	package netdiag
2	
3	import (
4		"cmp"
5		"fmt"
6		"math"
7		"net"
8		"net/netip"
9		"slices"
10		"strconv"
11		"time"
12	
13		"github.com/anthnel/devdesk/internal/netcheck"
14		"github.com/anthnel/devdesk/internal/nettrace"
15	)
16	
17	// pathStepKind says which kind of row a pathStep is.
18	type pathStepKind int
19	
20	// The kinds of row, in the order the column shows them.
21	const (
22		stepSource pathStepKind = iota
23		stepInterface
24		stepGateway
25		stepHop
26	)
27	
28	// pathRoute is the way out of this machine for the traced address.
29	type pathRoute struct {
30		Known     bool // false: the lookup failed; interface and gateway are undetermined
31		Interface string
32		Source    netip.Addr // invalid: the stack did not say
33		Gateway   netip.Addr // invalid: directly connected
34	}
35	
36	// pathStep is one row of the Path column.
37	type pathStep struct {
38		Kind  pathStepKind
39		Route pathRoute    // stepInterface, stepGateway
40		Hop   nettrace.Hop // stepHop
41	}
42	
43	const (
44		sourceLabel       = "this machine"
45		routeUndetermined = "undetermined"
46		gatewayDirect     = "directly connected"
47	)
48	
49	// newPathRoute converts a route lookup into a pathRoute. A failed lookup
50	// discards whatever the hop holds. Addresses are unmapped to IPv4 when they can be.
51	func newPathRoute(hop netcheck.RouteHop, err error) pathRoute {
52		if err != nil {
53			return pathRoute{}
54		}
55		return pathRoute{
56			Known:     true,
57			Interface: hop.Interface,
58			Source:    addrFromIP(hop.Source),
59			Gateway:   addrFromIP(hop.Gateway),
60		}
61	}
62	
63	// addrFromIP returns ip as an unmapped netip.Addr, or the zero Addr for a nil or invalid ip.
64	func addrFromIP(ip net.IP) netip.Addr {
65		addr, ok := netip.AddrFromSlice(ip)
66		if !ok {
67			return netip.Addr{}
68		}
69		return addr.Unmap()
70	}
71	
72	// pathSteps returns the rows of the Path column: the source, then the
73	// interface and gateway when route is not nil, then the hops by
74	// TTL. Nothing is returned before any route or hop exists. Unresolved hops and everything past the first target are dropped.
75	// Neither input is modified.
76	func pathSteps(route *pathRoute, hops []nettrace.Hop) []pathStep {
77		if route == nil && len(hops) == 0 {
78			return nil
79		}
80		steps := []pathStep{{Kind: stepSource}}
81		if route != nil {
82			steps = append(steps,
83				pathStep{Kind: stepInterface, Route: *route},
84				pathStep{Kind: stepGateway, Route: *route},
85			)
86		}
87		for _, h := range visibleHops(hops) {
88			steps = append(steps, pathStep{Kind: stepHop, Hop: h})
89		}
90		return steps
91	}
92	
93	// visibleHops returns a sorted copy of hops without the unresolved ones and
94	// without those past the lowest target TTL.
95	func visibleHops(hops []nettrace.Hop) []nettrace.Hop {
96		last := math.MaxInt
97		for _, h := range hops {
98			if h.Kind == nettrace.HopTarget {
99				last = min(last, h.TTL)
100			}
101		}
102		out := make([]nettrace.Hop, 0, len(hops))
103		for _, h := range hops {
104			if h.Kind != nettrace.HopUnresolved && h.TTL <= last {
105				out = append(out, h)
106			}
107		}
108		slices.SortStableFunc(out, func(a, b nettrace.Hop) int { return cmp.Compare(a.TTL, b.TTL) })
109		return out
110	}
111	
112	// hopCell is the TTL of a hop row; empty for the local rows.
113	func (s pathStep) hopCell() string {
114		if s.Kind != stepHop {
115			return ""
116		}
117		return strconv.Itoa(s.Hop.TTL)
118	}
119	
120	// stepCell names the kind of row.
121	func (s pathStep) stepCell() string {
122		switch s.Kind {
123		case stepSource:
124			return "source"
125		case stepInterface:
126			return "interface"
127		case stepGateway:
128			return "gateway"
129		}
130		return s.Hop.Kind.String()
131	}
132	
133	// addressCell is the main text of the row.
134	func (s pathStep) addressCell() string {
135		switch s.Kind {
136		case stepSource:
137			return sourceLabel
138		case stepInterface:
139			return s.Route.interfaceText()
140		case stepGateway:
141			return s.Route.gatewayText()
142		}
143		return addrOrDash(s.Hop.Addr)
144	}
145	
146	// rttCell is the round-trip time of a hop that answered; "-" otherwise.
147	func (s pathStep) rttCell() string {
148		if s.Kind != stepHop {
149			return ""
150		}
151		if s.Hop.RTT <= 0 {
152			return "-"
153		}
154		return fmt.Sprintf("%.1f ms", float64(s.Hop.RTT)/float64(time.Millisecond))
155	}
156	
157	// interfaceText is the interface name, followed by the source address when known.
158	func (r pathRoute) interfaceText() string {
159		if !r.Known || (r.Interface == "" && !r.Source.IsValid()) {
160			return routeUndetermined
161		}
162		name := r.Interface
163		if name == "" {
164			name = "unnamed"
165		}
166		if !r.Source.IsValid() {
167			return name
168		}
169		return name + " (" + r.Source.String() + ")"
170	}
171	
172	// gatewayText is the gateway address, or says the destination is directly connected.
173	func (r pathRoute) gatewayText() string {
174		switch {
175		case !r.Known:
176			return routeUndetermined
177		case !r.Gateway.IsValid():
178			return gatewayDirect
179		}
180		return r.Gateway.String()
181	}
182	
183	// addrOrDash formats an address, or "-" when there is none.
184	func addrOrDash(a netip.Addr) string {
185		if !a.IsValid() {
186			return "-"
187		}
188		return a.String()
189	}
190

